import { useState, useEffect, useCallback, memo } from 'react';
import { useParams, useNavigate } from 'react-router-dom';
import {
  Play, ExternalLink, Star, Calendar, Clock, Globe,
  Film, Tv, Shield, Zap, Heart, Bookmark, BookmarkCheck,
  Copy, Share2, ChevronDown, X, Filter, Check
} from 'lucide-react';
import { getDetail, getImdbId, img } from '../lib/tmdb';
import {
  generateMovieEmbedSources,
  generateTVEmbedSources,
  generateDirectStreamLinks,
  getStreamLinksForItem,
  getStreamQuality,
  getStreamServerName,
  type StreamLink
} from '../lib/streamSources';
import { useSettings } from '../contexts/SettingsContext';
import { useToast } from '../contexts/ToastContext';
import { useHistory } from '../contexts/HistoryContext';
import { PageSpinner } from '../components/Spinner';

const QUALITY_FILTERS = ['All', '4K', '1080p', '720p', '480p'];
const SERVER_FILTERS = ['All', 'Vidcloud', 'Streamtape', 'Doodstream', 'Upstream', 'Fembed', 'Direct'];

function StreamsPageInner() {
  const { type, id } = useParams<{ type: string; id: string }>();
  const navigate = useNavigate();
  const { settings } = useSettings();
  const { addToast } = useToast();
  const { addToHistory } = useHistory();

  const mediaType = (type === 'movie' || type === 'tv') ? type : 'movie';
  const mediaId = parseInt(id || '0', 10);
  const [detail, setDetail] = useState<any>(null);
  const [streams, setStreams] = useState<StreamLink[]>([]);
  const [loading, setLoading] = useState(true);
  const [qualityFilter, setQualityFilter] = useState('All');
  const [serverFilter, setServerFilter] = useState('All');
  const [showFilters, setShowFilters] = useState(false);
  const [inWatchlist, setInWatchlist] = useState(false);

  const loadWatchlist = useCallback(() => {
    try {
      const stored = localStorage.getItem('watchlist-ids');
      return stored ? JSON.parse(stored) : [];
    } catch { return []; }
  }, []);

  useEffect(() => {
    const loadData = async () => {
      setLoading(true);
      try {
        const detailData = await getDetail(mediaType, mediaId);
        setDetail(detailData);

        const imdbId = await getImdbId(mediaType, mediaId);
        const idParam = imdbId || String(mediaId);

        let loadedStreams: StreamLink[] = [];

        if (mediaType === 'movie') {
          loadedStreams = [
            ...generateMovieEmbedSources(idParam, mediaId),
            ...generateDirectStreamLinks(idParam, mediaId, 'movie'),
          ];
        } else {
          loadedStreams = [
            ...generateTVEmbedSources(idParam, mediaId, 1, 1),
            ...generateDirectStreamLinks(idParam, mediaId, 'tv', 1, 1),
          ];
        }

        setStreams(loadedStreams);
        setInWatchlist(loadWatchlist().includes(mediaId));

        addToHistory({
          id: mediaId,
          type: mediaType,
          title: detailData.title ?? detailData.name ?? '',
          poster_path: detailData.poster_path || null,
        });
      } catch (error) {
        console.error('Error loading streams:', error);
      } finally {
        setLoading(false);
      }
    };

    loadData();
  }, [mediaType, mediaId, addToHistory, loadWatchlist]);

  const toggleWatchlist = useCallback(() => {
    const newWatchlist = inWatchlist
      ? loadWatchlist().filter((id: number) => id !== mediaId)
      : [...loadWatchlist(), mediaId];
    setInWatchlist(!inWatchlist);
    localStorage.setItem('watchlist-ids', JSON.stringify(newWatchlist));
    addToast(
      inWatchlist ? 'Removed from watchlist' : 'Added to watchlist',
      inWatchlist ? 'info' : 'success'
    );
  }, [inWatchlist, mediaId, loadWatchlist, addToast]);

  const shareContent = useCallback(() => {
    const url = `${window.location.origin}/${mediaType}/${mediaId}`;
    navigator.clipboard.writeText(url).then(() => {
      addToast('Link copied to clipboard!', 'copy');
    }).catch(() => {
      addToast('Failed to copy link', 'error');
    });
  }, [mediaType, mediaId, addToast]);

  const filteredStreams = streams.filter(stream => {
    const quality = getStreamQuality(stream.quality);
    const server = getStreamServerName(stream.server);
    if (qualityFilter !== 'All' && quality !== qualityFilter) return false;
    if (serverFilter !== 'All' && !server.includes(serverFilter)) return false;
    return true;
  });

  const qualityMap: Record<string, string> = {
    '4K': '🔥 4K (2160p)',
    '1080p': '✨ 1080p (Full HD)',
    '720p': '👍 720p (HD)',
    '480p': '📺 480p (SD)',
  };

  const title = detail?.title ?? detail?.name ?? 'Loading...';
  const year = (detail?.release_date ?? detail?.first_air_date ?? '').slice(0, 4);
  const poster = detail?.poster_path ? img(detail.poster_path, 'w342') : null;
  const backdrop = detail?.backdrop_path ? img(detail.backdrop_path, 'w780') : null;

  if (loading) return <PageSpinner />;

  return (
    <div className="min-h-screen bg-[#0a0a0f]">
      {/* Hero backdrop */}
      {backdrop && (
        <div className="relative h-48 sm:h-64 md:h-80 overflow-hidden">
          <img src={backdrop} alt="" className="w-full h-full object-cover" loading="lazy" />
          <div className="absolute inset-0 bg-gradient-to-t from-[#0a0a0f] via-[#0a0a0f]/80 to-[#0a0a0f]/50" />
        </div>
      )}

      <div className="max-w-full lg:max-w-[1600px] xl:max-w-[2000px] 2xl:max-w-[2560px] mx-auto px-4 sm:px-6 -mt-24 relative z-10">
        {/* Header */}
        <div className="flex flex-col sm:flex-row gap-4 mb-6">
          {/* Poster */}
          {poster && (
            <div className="shrink-0 w-28 sm:w-36 rounded-xl overflow-hidden shadow-2xl ring-1 ring-white/10">
              <img src={poster} alt={title} className="w-full" loading="lazy" />
            </div>
          )}

          {/* Info */}
          <div className="flex-1">
            <div className="flex flex-wrap items-start justify-between gap-2">
              <div>
                <h1 className="text-xl sm:text-2xl lg:text-3xl font-black text-white">{title}</h1>
                <div className="flex items-center gap-3 mt-2 text-sm text-white/50">
                  {year && <span>{year}</span>}
                  {detail?.vote_average && (
                    <span className="flex items-center gap-1">
                      <Star size={14} className="text-amber-400" fill="currentColor" />
                      {detail.vote_average.toFixed(1)}
                    </span>
                  )}
                  <span className="px-2 py-0.5 bg-white/10 rounded text-xs uppercase">{mediaType}</span>
                </div>
              </div>
              <div className="flex gap-2">
                <button
                  onClick={toggleWatchlist}
                  className={`flex items-center gap-2 px-4 py-2 rounded-lg transition-all ${
                    inWatchlist
                      ? 'bg-emerald-500 text-white'
                      : 'bg-white/10 text-white hover:bg-white/20'
                  }`}
                >
                  {inWatchlist ? <BookmarkCheck size={16} /> : <Bookmark size={16} />}
                  <span className="hidden sm:inline">{inWatchlist ? 'In List' : 'Watchlist'}</span>
                </button>
                <button
                  onClick={shareContent}
                  className="flex items-center gap-2 px-4 py-2 bg-white/10 text-white hover:bg-white/20 rounded-lg transition-all"
                >
                  <Share2 size={16} />
                </button>
              </div>
            </div>
          </div>
        </div>

        {/* Filters */}
        <div className="flex flex-wrap items-center gap-2 mb-4">
          <button
            onClick={() => setShowFilters(!showFilters)}
            className="flex items-center gap-2 px-4 py-2 bg-white/10 hover:bg-white/15 text-white rounded-lg transition-all"
          >
            <Filter size={16} />
            Filters
          </button>

          {showFilters && (
            <>
              <div className="flex items-center gap-1">
                <span className="text-white/40 text-xs mr-1">Quality:</span>
                {QUALITY_FILTERS.map(q => (
                  <button
                    key={q}
                    onClick={() => setQualityFilter(q)}
                    className={`px-3 py-1.5 rounded-lg text-xs transition-all ${
                      qualityFilter === q
                        ? 'bg-emerald-500 text-white'
                        : 'bg-white/5 text-white/50 hover:bg-white/10 hover:text-white'
                    }`}
                  >
                    {q === 'All' ? q : qualityMap[q] || q}
                  </button>
                ))}
              </div>
              <div className="flex items-center gap-1">
                <span className="text-white/40 text-xs mr-1">Server:</span>
                {SERVER_FILTERS.map(s => (
                  <button
                    key={s}
                    onClick={() => setServerFilter(s)}
                    className={`px-3 py-1.5 rounded-lg text-xs transition-all ${
                      serverFilter === s
                        ? 'bg-emerald-500 text-white'
                        : 'bg-white/5 text-white/50 hover:bg-white/10 hover:text-white'
                    }`}
                  >
                    {s}
                  </button>
                ))}
              </div>
            </>
          )}

          <span className="text-white/30 text-xs ml-auto">
            {filteredStreams.length} stream{filteredStreams.length !== 1 ? 's' : ''} available
          </span>
        </div>

        {/* Stream cards */}
        {filteredStreams.length > 0 ? (
          <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 xl:grid-cols-4 gap-3">
            {filteredStreams.map((stream, index) => {
              const quality = getStreamQuality(stream.quality);
              const server = getStreamServerName(stream.server);
              const isDefault = index === 0;

              return (
                <div
                  key={`${stream.name}-${index}`}
                  className="group relative bg-white/5 hover:bg-white/10 border border-white/5 hover:border-emerald-500/30 rounded-xl overflow-hidden transition-all hover:-translate-y-0.5 hover:shadow-lg"
                >
                  <div className="p-4">
                    <div className="flex items-start justify-between mb-3">
                      <div className="flex-1">
                        <h3 className="text-white font-semibold text-sm">{stream.name}</h3>
                        <div className="flex items-center gap-2 mt-1">
                          <span className={`px-2 py-0.5 rounded text-[10px] font-bold uppercase ${
                            quality === '4K' ? 'bg-purple-500/20 text-purple-400' :
                            quality === '1080p' ? 'bg-emerald-500/20 text-emerald-400' :
                            quality === '720p' ? 'bg-blue-500/20 text-blue-400' :
                            'bg-gray-500/20 text-gray-400'
                          }`}>
                            {quality}
                          </span>
                          <span className="text-white/30 text-[10px]">{server}</span>
                        </div>
                      </div>
                      {isDefault && (
                        <span className="px-2 py-0.5 bg-emerald-500/20 text-emerald-400 rounded text-[10px] font-bold">
                          DEFAULT
                        </span>
                      )}
                    </div>

                    <div className="flex items-center gap-2 text-xs text-white/40">
                      {stream.quality === '4K' && <Zap size={12} className="text-purple-400" />}
                      <Shield size={12} className="text-emerald-400" />
                      <span>HD</span>
                    </div>
                  </div>

                  <div className="flex gap-2 p-4 pt-0">
                    <button
                      onClick={() => navigate(`/watch/${mediaType}/${mediaId}`)}
                      className="flex-1 flex items-center justify-center gap-2 px-4 py-2.5 bg-emerald-500 hover:bg-emerald-400 text-white rounded-lg transition-all text-sm font-semibold shadow-lg shadow-emerald-500/20 hover:shadow-emerald-500/40 hover:scale-105 active:scale-95"
                    >
                      <Play size={14} fill="white" />
                      Watch
                    </button>
                    <a
                      href={stream.url}
                      target="_blank"
                      rel="noopener noreferrer"
                      className="px-3 py-2.5 bg-white/10 hover:bg-white/20 text-white rounded-lg transition-all"
                      aria-label="Open in new tab"
                    >
                      <ExternalLink size={14} />
                    </a>
                  </div>
                </div>
              );
            })}
          </div>
        ) : (
          <div className="text-center py-24">
            <Film size={56} className="mx-auto text-white/10 mb-5" />
            <p className="text-white/30 text-lg font-medium">No streams found</p>
            <p className="text-white/20 text-sm mt-2">Try adjusting your filters</p>
          </div>
        )}
      </div>
    </div>
  );
}

export default memo(StreamsPageInner);